action.command:
node --input-type=module <<'EOF'
import { execSync } from 'child_process';
const stdin = JSON.parse(require('fs').readFileSync('/dev/stdin', 'utf8'));
const filePath = stdin.file?.path ?? '';
const component = filePath.split('/').pop()?.replace('.ts', '') ?? 'unknown';
try {
  execSync(`curl -s -X POST http://localhost:3000/api/graph/check-drift -H 'Content-Type: application/json' -d '${JSON.stringify({component, triggeredBy: 'PostFileSave', filePath})}'`);
} catch (e) { /* API may not be running */ }
EOF

node --input-type=module <<'EOF'
const stdin = JSON.parse(require('fs').readFileSync('/dev/stdin', 'utf8'));
const { taskId, workflowId, status } = stdin;
if (status !== 'completed') process.exit(0);
try {
  const { execSync } = require('child_process');
  execSync(`curl -s -X POST http://localhost:3000/api/events -H 'Content-Type: application/json' -d '${JSON.stringify({type: 'task.completed', source: 'bob-hook', payload: {taskId, workflowId, status}})}'`);
} catch (e) { /* API may not be running */ }
EOF

node --input-type=module <<'EOF'
try {
  const { execSync } = require('child_process');
  const snapshot = execSync('curl -s http://localhost:3001/trajectory-snapshot').toString();
  const parsed = JSON.parse(snapshot);
  console.log(JSON.stringify({
    epochContext: {
      trajectorySnapshot: parsed,
      message: `EPOCH context loaded: coupling=${parsed.couplingScore?.toFixed(2)}, boundary=${parsed.boundaryIntegrityScore?.toFixed(2)}, drift=${parsed.activeDriftFindings ?? 0} finding(s)`
    }
  }));
} catch (e) {
  console.log(JSON.stringify({ epochContext: { message: 'EPOCH API not running — start with pnpm dev' } }));
}
EOF
